const emailRegex = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g
const collectEmails = value => {
  if (value === undefined || value === null) {
    return
  }
  if (typeof value === 'string') {
    const matches = value.match(emailRegex) || []
    for (const email of matches) {
      allowedEmails.add(email.toLowerCase())
    }
    return
  }
  if (Array.isArray(value)) {
    for (const entry of value) {
      collectEmails(entry)
    }
    return
  }
  if (typeof value === 'object') {
    if (value.stringValue !== undefined) {
      collectEmails(value.stringValue)
      return
    }
    if (value.arrayValue !== undefined) {
      collectEmails(value.arrayValue?.values || [])
      return
    }
    for (const nested of Object.values(value)) {
      collectEmails(nested)
    }
  }
}
const allowedEmails = new Set()
for (const item of items) {
  collectEmails(item.json)
}
return [{
  json: {
    supplierEmails: Array.from(allowedEmails).sort(),
    suppliersFetched: items.length,
    fetchedAt: new Date().toISOString()
  }
}]

const emailRegex = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g
const supplierInput = this.getInputData(1) || []
const supplierEmails = new Set()
if (supplierInput.length > 0) {
  const allowlist = supplierInput[0]?.json?.supplierEmails || []
  for (const email of Array.isArray(allowlist) ? allowlist : []) {
    if (typeof email === 'string' && email.trim() !== '') {
      supplierEmails.add(email.trim().toLowerCase())
    }
  }
}
const allowAll = supplierEmails.size === 0
const extractEmails = headerValue => {
  if (typeof headerValue !== 'string' || headerValue.trim() === '') {
    return []
  }
  const matches = headerValue.match(emailRegex) || []
  return matches.map(email => email.toLowerCase())
}
const itemsWithAttachments = []
for (const item of items) {
  const headers = item.json?.payload?.headers || []
  const fromHeader = headers.find(h => h.name === 'From')?.value || ''
  const dateHeader = headers.find(h => h.name === 'Date')?.value || ''
  const messageEmails = extractEmails(fromHeader)
  const matchedEmails = allowAll ? messageEmails : messageEmails.filter(email => supplierEmails.has(email))
  if (!allowAll && matchedEmails.length === 0) {
    continue
  }
  const attachments = item.json?.payload?.parts || []
  const attachmentParts = attachments.filter(part => part.filename && part.body?.attachmentId)
  for (const part of attachmentParts) {
    itemsWithAttachments.push({
      json: {
        messageId: item.json.id,
        threadId: item.json.threadId,
        snippet: item.json.snippet,
        attachmentId: part.body.attachmentId,
        attachmentName: part.filename,
        mimeType: part.mimeType,
        invoiceSource: fromHeader || '',
        invoiceDate: dateHeader || '',
        allowedSupplierEmails: Array.from(supplierEmails),
        matchedSupplierEmails: matchedEmails,
        supplierAllowlistEnforced: !allowAll
      }
    })
  }
}
return itemsWithAttachments

const DEFAULT_MIME = 'application/pdf'
return items.map(item => {
  const { json, binary } = item
  const attachmentName = json.attachmentName || 'invoice.pdf'
  const mimeType = json.mimeType || DEFAULT_MIME
  const allowedSupplierEmails = Array.isArray(json.allowedSupplierEmails) ? json.allowedSupplierEmails : []
  const matchedSupplierEmails = Array.isArray(json.matchedSupplierEmails) ? json.matchedSupplierEmails : []
  const primaryMatch = matchedSupplierEmails.length > 0 ? matchedSupplierEmails[0] : ''
  return {
    json: {
      emailMetadata: {
        messageId: json.messageId,
        threadId: json.threadId,
        snippet: json.snippet || '',
        source: json.invoiceSource || '',
        emailDate: json.invoiceDate || '',
        attachmentName,
        mimeType,
        supplierAllowlistEnforced: Boolean(json.supplierAllowlistEnforced),
        allowedSupplierEmails,
        matchedSupplierEmails,
        primarySupplierEmail: primaryMatch
      }
    },
    binary: {
      data: {
        data: binary.data.data,
        fileName: attachmentName,
        mimeType
      }
    }
  }
})

const now = new Date().toISOString()
return items.map(item => {
  const parserResult = item.json.parserResult || {}
  const metadata = item.json.emailMetadata || {}
  const safeNumber = value => {
    if (value === undefined || value === null || value === '') {
      return null
    }
    const numeric = Number(value)
    return Number.isNaN(numeric) ? null : numeric
  }
  const normalizeLineItems = Array.isArray(parserResult.lineItems) ? parserResult.lineItems : []
  const allowedSupplierEmails = Array.isArray(metadata.allowedSupplierEmails) ? metadata.allowedSupplierEmails : []
  const matchedSupplierEmails = Array.isArray(metadata.matchedSupplierEmails) ? metadata.matchedSupplierEmails : []
  const primarySupplierEmail = metadata.primarySupplierEmail || matchedSupplierEmails[0] || null
  return {
    json: {
      messageId: metadata.messageId || '',
      threadId: metadata.threadId || '',
      source: metadata.source || '',
      emailSnippet: metadata.snippet || '',
      emailDate: metadata.emailDate || '',
      attachmentName: metadata.attachmentName || '',
      mimeType: metadata.mimeType || '',
      issueDate: parserResult.issueDate || metadata.emailDate || '',
      total: safeNumber(parserResult.total),
      currency: parserResult.currency || null,
      supplierTaxId: parserResult.supplierTaxId || null,
      customerTaxId: parserResult.customerTaxId || null,
      invoiceNumber: parserResult.invoiceNumber || null,
      paymentReference: parserResult.paymentReference || null,
      lineItems: normalizeLineItems.map(item => ({
        description: item.description || '',
        quantity: safeNumber(item.quantity),
        unitPrice: safeNumber(item.unitPrice),
        total: safeNumber(item.total)
      })),
      rawParserResponse: parserResult,
      supplierAllowlistEnforced: Boolean(metadata.supplierAllowlistEnforced),
      allowedSupplierEmails,
      matchedSupplierEmails,
      primarySupplierEmail,
      createdAt: now,
      updatedAt: now
    }
  }
})
